class Aabb:
    """Axis-aligned bounding box: top-left corner (x, y) plus size (w, h)."""

    __slots__ = ("x", "y", "w", "h")

    def __init__(self, x, y, w, h):
        self.x = x
        self.y = y
        self.w = w
        self.h = h

    @property
    def left(self):
        return self.x

    @property
    def right(self):
        return self.x + self.w

    @property
    def top(self):
        return self.y

    @property
    def bottom(self):
        return self.y + self.h

    @property
    def cx(self):
        return self.x + self.w / 2.0

    @property
    def cy(self):
        return self.y + self.h / 2.0

    def overlaps(self, other):
        """True if the interiors of self and other intersect."""
        return (
            self.left < other.right
            and other.left < self.right
            and self.top < other.bottom
            and other.top < self.bottom
        )

    def resolve(self, other):
        """Push self out of static box `other` along the axis of least penetration.

        Returns the correction vector (dx, dy) that should be added to
        self.x/self.y. Direction points away from `other`'s center, i.e.
        toward self's side. Zero penetration or no overlap yields (0, 0).
        Ties in penetration depth are broken along x.
        """
        ox = min(self.right, other.right) - max(self.left, other.left)
        oy = min(self.bottom, other.bottom) - max(self.top, other.top)
        if ox <= 0 or oy <= 0:
            return (0, 0)

        if ox <= oy:  # tie (ox == oy) breaks toward x
            dx = ox if self.cx >= other.cx else -ox
            return (dx, 0)
        dy = oy if self.cy >= other.cy else -oy
        return (0, dy)


def resolve(a, b):
    """Module-level convenience wrapper: push box a out of static box b."""
    return a.resolve(b)
